#include <bits/stdc++.h>
using namespace std;

int main() {
    int rows, cols;
    cin >> rows >> cols;
    vector<string> board(rows);
    for (auto &r : board) cin >> r;
    const int BAD = -1000000000;
    if (board[0][0] == 'x') {
        puts("-1");
        return 0;
    }
    vector<int> prev(cols, BAD), left(cols), right(cols);
    prev[0] = 0;
    // Within a row the path is one horizontal run, either left-to-right or right-to-left.
    for (auto &row : board) {
        fill(left.begin(), left.end(), BAD);
        fill(right.begin(), right.end(), BAD);
        for (int j = 0; j < cols; j++)
            if (row[j] == '!') {
                int best = max(prev[j], j ? left[j - 1] : BAD);
                if (best != BAD) left[j] = best + 1;
            }
        for (int j = cols - 1; j >= 0; j--)
            if (row[j] == '!') {
                int best = max(prev[j], j + 1 < cols ? right[j + 1] : BAD);
                if (best != BAD) right[j] = best + 1;
            }
        for (int j = 0; j < cols; j++) prev[j] = max(left[j], right[j]);
    }
    printf("%d\n", prev[cols - 1] != BAD ? prev[cols - 1] : -1);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int rows = nextInt(), cols = nextInt();
        String[] board = new String[rows];
        for (int i = 0; i < rows; i++) board[i] = next();
        final int BAD = -1000000000;
        if (board[0].charAt(0) == 'x') {
            System.out.println(-1);
            return;
        }
        int[] prev = new int[cols], left = new int[cols], right = new int[cols];
        Arrays.fill(prev, BAD);
        prev[0] = 0;
        // Within a row the path is one horizontal run, either left-to-right or right-to-left.
        for (String row : board) {
            Arrays.fill(left, BAD);
            Arrays.fill(right, BAD);
            for (int j = 0; j < cols; j++)
                if (row.charAt(j) == '!') {
                    int best = Math.max(prev[j], j > 0 ? left[j - 1] : BAD);
                    if (best != BAD) left[j] = best + 1;
                }
            for (int j = cols - 1; j >= 0; j--)
                if (row.charAt(j) == '!') {
                    int best = Math.max(prev[j], j + 1 < cols ? right[j + 1] : BAD);
                    if (best != BAD) right[j] = best + 1;
                }
            for (int j = 0; j < cols; j++) prev[j] = Math.max(left[j], right[j]);
        }
        System.out.println(prev[cols - 1] != BAD ? prev[cols - 1] : -1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	rows, cols := int(nextInt()), int(nextInt())
	board := make([]string, rows)
	for i := range board {
		board[i] = next()
	}
	const BAD = -1000000000
	if board[0][0] == 'x' {
		fmt.Println(-1)
		return
	}
	prev := make([]int, cols)
	left := make([]int, cols)
	right := make([]int, cols)
	for j := range prev {
		prev[j] = BAD
	}
	prev[0] = 0
	// Within a row the path is one horizontal run, either left-to-right or right-to-left.
	for _, row := range board {
		for j := range left {
			left[j], right[j] = BAD, BAD
		}
		for j := 0; j < cols; j++ {
			if row[j] == '!' {
				best := prev[j]
				if j > 0 {
					best = max(best, left[j-1])
				}
				if best != BAD {
					left[j] = best + 1
				}
			}
		}
		for j := cols - 1; j >= 0; j-- {
			if row[j] == '!' {
				best := prev[j]
				if j+1 < cols {
					best = max(best, right[j+1])
				}
				if best != BAD {
					right[j] = best + 1
				}
			}
		}
		for j := range prev {
			prev[j] = max(left[j], right[j])
		}
	}
	if prev[cols-1] != BAD {
		fmt.Println(prev[cols-1])
	} else {
		fmt.Println(-1)
	}
}
